import{_ as e,c as r,o as t,ae as o}from"./chunks/framework.CHDT0Kbg.js";const m=JSON.parse('{"title":"常見問題","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/faq.md","filePath":"zh-TW/guide/faq.md","lastUpdated":1795170900000}'),i={name:"zh-TW/guide/faq.md"};function l(s,a,h,n,d,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="常見問題" tabindex="-1">常見問題 <a class="header-anchor" href="#常見問題" aria-label="Permalink to &quot;常見問題&quot;">​</a></h1><p>關於 Persim 的快速解答。</p><h3 id="persim-收費嗎" tabindex="-1">Persim 收費嗎？ <a class="header-anchor" href="#persim-收費嗎" aria-label="Permalink to &quot;Persim 收費嗎？&quot;">​</a></h3><p>可以從 Mac App Store 免費下載，基礎瀏覽功能可直接使用。部分進階功能透過應用程式內購買解鎖，免費版會在分頁列顯示一個小標記。</p><h3 id="支援哪些系統" tabindex="-1">支援哪些系統？ <a class="header-anchor" href="#支援哪些系統" aria-label="Permalink to &quot;支援哪些系統？&quot;">​</a></h3><p>Persim 面向 macOS 12 及以上，相容 Apple Silicon 與 Intel 晶片的 Mac。</p><h3 id="我的資料會上傳嗎" tabindex="-1">我的資料會上傳嗎？ <a class="header-anchor" href="#我的資料會上傳嗎" aria-label="Permalink to &quot;我的資料會上傳嗎？&quot;">​</a></h3><p>不需要帳戶。歷史、書籤、工作階段和下載紀錄都留在你的 Mac 上。需要連網的功能（例如更新廣告訂閱）只會取得它需要的內容；Cookie 管理員裡可以清除網站資料。</p><h3 id="怎麼匯入其他瀏覽器的書籤" tabindex="-1">怎麼匯入其他瀏覽器的書籤？ <a class="header-anchor" href="#怎麼匯入其他瀏覽器的書籤" aria-label="Permalink to &quot;怎麼匯入其他瀏覽器的書籤？&quot;">​</a></h3><p>在 Chrome 或 Edge 中把書籤匯出為 HTML 檔案，再在 Persim 書籤管理員裡選擇「匯入 HTML」。多層資料夾和重複連結都會自動處理。</p><h3 id="怎麼儲存網頁上的影片" tabindex="-1">怎麼儲存網頁上的影片？ <a class="header-anchor" href="#怎麼儲存網頁上的影片" aria-label="Permalink to &quot;怎麼儲存網頁上的影片？&quot;">​</a></h3><p>開啟偵測面板，選擇辨識到的影片並下載。分成多段的影片會合成一個 MP4，下載完可以用你平時用的應用程式開啟。</p><h3 id="怎麼切換介面語言" tabindex="-1">怎麼切換介面語言？ <a class="header-anchor" href="#怎麼切換介面語言" aria-label="Permalink to &quot;怎麼切換介面語言？&quot;">​</a></h3><p>開啟 <code>persim://settings</code> → 「一般」→「介面語言」。應用程式提供 25 種語言，重新開啟視窗後生效。</p><h3 id="還有其他問題" tabindex="-1">還有其他問題？ <a class="header-anchor" href="#還有其他問題" aria-label="Permalink to &quot;還有其他問題？&quot;">​</a></h3><p>寫信到 <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong>，告訴我們你想做什麼，我們會盡力幫忙。</p>',16)])])}const u=e(i,[["render",l]]);export{m as __pageData,u as default};
